1: import { type Diagnosis } from '@openmrs/esm-framework';
2: 
3: /**
4:  * A display-level aggregate of one diagnosis (keyed by concept UUID, or exact text for
5:  * non-coded diagnoses) across the encounters of a visit. The `uuid`, `display`, and
6:  * `diagnosis` reference come from one contributing encounter diagnosis so the entry has
7:  * a stable key, but `rank` and `certainty` are aggregated across all duplicates and may
8:  * not match that record. It must not be treated as an encounter diagnosis.
9:  */
10: export interface DedupedDiagnosis {
11:   uuid: string;
12:   display?: string;
13:   diagnosis?: Diagnosis['diagnosis'];
14:   rank?: number;
15:   // Deliberately `string`, not the CONFIRMED/PROVISIONAL union: this is a display-level
16:   // passthrough of whatever other writers stored, which may lie outside the known enum.
17:   certainty?: string;
18: }
19: 
20: /**
21:  * Collapses repeats of the same diagnosis recorded across multiple encounters of a visit
22:  * into a single entry and sorts the result by rank (primary first). Duplicates are merged
23:  * with: rank = the minimum across duplicates (primary if primary in any encounter), and
24:  * certainty = the strongest across duplicates (CONFIRMED if confirmed in any encounter).
25:  * Both rules are independent of encounter order.
26:  */
27: export function dedupeDiagnoses(diagnoses: Array<Diagnosis>): Array<DedupedDiagnosis> {
28:   const merged = new Map<string, DedupedDiagnosis>();
29:   const result: Array<DedupedDiagnosis> = [];
30: 
31:   for (const { uuid, display, diagnosis, rank, certainty } of diagnoses) {
32:     const key = diagnosis?.coded?.uuid ?? diagnosis?.nonCoded;
33:     const existing = key ? merged.get(key) : undefined;
34: 
35:     if (!existing) {
36:       const entry: DedupedDiagnosis = { uuid, display, diagnosis, rank, certainty };
37:       if (key) {
38:         merged.set(key, entry);
39:       }
40:       result.push(entry);
41:     } else {
42:       existing.rank = minRank(existing.rank, rank);
43:       existing.certainty = strongerCertainty(existing.certainty, certainty);
44:     }
45:   }
46: 
47:   return result.sort((a, b) => (a.rank ?? Number.MAX_SAFE_INTEGER) - (b.rank ?? Number.MAX_SAFE_INTEGER));
48: }
49: 
50: function minRank(a: number | undefined, b: number | undefined): number | undefined {
51:   if (a == null) {
52:     return b;
53:   }
54:   if (b == null) {
55:     return a;
56:   }
57:   return Math.min(a, b);
58: }
59: 
60: /**
61:  * Deterministic certainty precedence: CONFIRMED > PROVISIONAL > any other stored value >
62:  * unset. Values of equal precedence (two out-of-enum values from other writers) tie-break
63:  * lexicographically, so the merge result never depends on encounter order.
64:  */
65: function strongerCertainty(a: string | undefined, b: string | undefined): string | undefined {
66:   const precedence = (value: string | undefined) =>
67:     value === 'CONFIRMED' ? 3 : value === 'PROVISIONAL' ? 2 : value != null ? 1 : 0;
68:   if (precedence(a) !== precedence(b)) {
69:     return precedence(a) > precedence(b) ? a : b;
70:   }
71:   if (a != null && b != null) {
72:     return a <= b ? a : b;
